const VANCHINATHAN_INFO={id:"vanchinathan",title:"Vanchinathan",quickStats:[{label:"Born",value:"1886, Senkottai",icon:"📍"},{label:"Died",value:"1911",icon:"🕯️"},{label:"Region",value:"Tirunelveli, Tamil Nadu",icon:"🗺️"},{label:"Movement",value:"South Indian Revolutionary Society",icon:"🇮🇳"},{label:"Associated With",value:"V. O. Chidambaram Pillai's Circle",icon:"👥"},{label:"Historical Role",value:"Anti-Colonial Revolutionary",icon:"📜"}]},HISTORY_TEXT={title:"A Young Revolutionary in Colonial Tirunelveli",paragraphs:["Vanchinathan (born Sankara Krishna Vanchinathan Iyer in 1886) was a young revolutionary from the Tirunelveli region of present-day Tamil Nadu, active during a period of intense nationalist and revolutionary ferment in South India in the early 20th century.","He was associated with a circle of young nationalists influenced by the broader Swadeshi movement and by regional leaders such as V. O. Chidambaram Pillai, who organized labor and shipping resistance against British colonial commercial interests in the Tirunelveli-Tuticorin region.","This period saw significant unrest in the region, driven by opposition to British colonial administration, harsh treatment of nationalist leaders, and broader anti-colonial sentiment across South India that paralleled revolutionary activity happening in Bengal and other parts of the country at the time.","Vanchinathan is remembered in regional and national historical memory as part of this early generation of South Indian revolutionaries whose actions, however controversial, reflected the depth of resistance to colonial rule that existed well before the broader mass movements of the 1920s and beyond."]},TIMELINE_EVENTS=[{era:"1886",title:"Born in Senkottai",description:"Vanchinathan was born in the Tirunelveli region of the Madras Presidency."},{era:"1900s",title:"Swadeshi-Era Nationalism",description:"Grew up during the Swadeshi movement's rise in South India, influenced by regional nationalist leaders."},{era:"1908",title:"Tirunelveli-Tuticorin Unrest",description:"The region saw major unrest connected to V. O. Chidambaram Pillai's labor and shipping resistance movement."},{era:"1911",title:"Historical Turning Point",description:"Vanchinathan's revolutionary activity culminated in a widely documented event in 1911 that is a significant part of South India's revolutionary history."},{era:"1911",title:"Death",description:"Vanchinathan died in 1911, becoming a figure remembered in the history of South India's early revolutionary movement."}],ACTIVITIES=[{title:"Involvement in Nationalist Circles",description:"Part of a network of young South Indian nationalists engaged in anti-colonial organizing during the early 1900s."},{title:"Influence of the Swadeshi Movement",description:"Shaped by the broader Swadeshi movement's emphasis on self-reliance and resistance to British economic and political control."},{title:"Connection to Regional Resistance",description:"Operated within the context of wider unrest in the Tirunelveli-Tuticorin region against colonial administration."},{title:"Part of a Broader Revolutionary Network",description:"His activities are studied by historians as part of the loosely connected revolutionary movements active across British India in this period."}],SIGNIFICANCE_TEXT={paragraphs:["Vanchinathan's story is part of the broader history of early 20th-century revolutionary nationalism in India, a period when a number of young activists across different regions — Bengal, Maharashtra, Punjab, and South India among them — pursued various forms of resistance against British colonial rule, occurring alongside the more widely known non-violent mass movements of later decades.","Historians regard this period as significant for demonstrating the geographic breadth of anti-colonial sentiment in India, extending well beyond the more commonly documented centers of nationalist activity, and for shaping the political climate that eventually contributed to India's independence movement as a whole."]},GALLERY_QUERIES=["Tirunelveli Tamil Nadu historical","Tuticorin harbor early 20th century","colonial era Madras Presidency"],REFERENCES=[{text:"Tamil Nadu State Archives — records on early 20th-century revolutionary activity in Tirunelveli.",link:"#"},{text:"Historical studies on V. O. Chidambaram Pillai and the Swadeshi Steam Navigation movement.",link:"#"},{text:"Academic accounts of South Indian revolutionary nationalism, 1900s–1910s.",link:"#"}];